CREATE TABLE watch_parties(id uuid PRIMARY KEY,owner_profile uuid NOT NULL REFERENCES profiles ON DELETE CASCADE,asset_id uuid NOT NULL REFERENCES media_assets ON DELETE CASCADE,name varchar(80) NOT NULL,invite_hash varchar(64) NOT NULL UNIQUE,position_seconds double precision NOT NULL DEFAULT 0 CHECK(position_seconds>=0),playing boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX party_expiration ON watch_parties(expires_at);
CREATE TABLE party_members(room_id uuid REFERENCES watch_parties ON DELETE CASCADE,profile_id uuid REFERENCES profiles ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(room_id,profile_id));
CREATE TABLE party_messages(id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES watch_parties ON DELETE CASCADE,profile_id uuid NOT NULL REFERENCES profiles ON DELETE CASCADE,client_id uuid NOT NULL,text varchar(500) NOT NULL,kind varchar(10) NOT NULL CHECK(kind IN ('CHAT','REACTION')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(room_id,profile_id,client_id));
CREATE INDEX party_messages_recent ON party_messages(room_id,created_at DESC);
CREATE TABLE party_preferences(room_id uuid REFERENCES watch_parties ON DELETE CASCADE,profile_id uuid REFERENCES profiles ON DELETE CASCADE,genre_id int REFERENCES genres ON DELETE CASCADE,PRIMARY KEY(room_id,profile_id,genre_id),FOREIGN KEY(room_id,profile_id) REFERENCES party_members ON DELETE CASCADE);
CREATE TABLE party_votes(room_id uuid REFERENCES watch_parties ON DELETE CASCADE,profile_id uuid REFERENCES profiles ON DELETE CASCADE,content_id uuid REFERENCES content ON DELETE CASCADE,vote int NOT NULL CHECK(vote BETWEEN -1 AND 1),PRIMARY KEY(room_id,profile_id,content_id),FOREIGN KEY(room_id,profile_id) REFERENCES party_members ON DELETE CASCADE);
